{
  "name": "@amykit/plugin-notify-inbox",
  "version": "0.6.0",
  "description": "Announcements as a file on disk plus a desktop notification.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/notify-inbox"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@amykit/core": "^0.6.0",
    "@amykit/plugin-notify-fanout": "^0.6.0"
  },
  "devDependencies": {
    "@amykit/test-fixtures": "^0.1.0"
  }
}

import fs from "node:fs";
import path from "node:path";
import { CommandRunner, ConfigSchema } from "@amykit/core";
import { Channel } from "@amykit/plugin-notify-fanout";

/** What this plugin needs told to it, and nothing more. */
export const configSchema = {
  directory: {
    type: "string",
    description: "where the questions are left, relative to the workspace",
    default: "needs-input",
  },
} satisfies ConfigSchema;

/**
 * Writes the announcement to a directory of files the operator can answer in
 * their own time, and raises a desktop notification so they know it is there.
 *
 * The file is the durable half: a notification that is missed is gone, but
 * the question stays on disk until it is dealt with.
 */
export function inboxChannel(directory: string, runner: CommandRunner): Channel {
  return {
    name: "inbox",
    async deliver(announcement) {
      fs.mkdirSync(directory, { recursive: true });

      const stamp = new Date().toISOString().replace(/[:.]/g, "");
      const file = path.join(directory, `${stamp}-${announcement.workId}.md`);

      fs.writeFileSync(
        file,
        [
          `# ${announcement.workId}`,
          ``,
          `State: ${announcement.state}`,
          `Asked: ${new Date().toISOString()}`,
          ``,
          announcement.text,
          ``,
          `---`,
          `Answer on the ticket, then delete this file.`,
          ``,
        ].join("\n"),
        "utf-8",
      );

      await runner.run("osascript", [
        "-e",
        `display notification ${quote(announcement.text)} with title ${quote(
          `amy ${announcement.workId}`,
        )}`,
      ]);
    },
  };
}

/** AppleScript string literal, kept to one line so a newline cannot break it. */
function quote(text: string): string {
  const flattened = text.replace(/\s+/g, " ").trim();
  const escaped = flattened.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  return `"${escaped}"`;
}

import path from "node:path";
import { definePlugin } from "@amykit/core";
import { CHANNEL_COLLECTION } from "@amykit/plugin-notify-fanout";
import { configSchema, inboxChannel } from "./inboxChannel.js";

export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-notify-inbox",
  configSchema,
  register(registry, ctx) {
    const directory = path.join(ctx.paths.state, ctx.config.directory);
    registry.contribute(CHANNEL_COLLECTION, "inbox", inboxChannel(directory, ctx.runner));
  },
});
